package tools

import "github.com/Stack-Cairn/K-brain/internal/ai"

// Original LiveAgent fsTools parameter schemas, including descriptions and bounds.
var liveagentDefinitions = map[string]ai.Tool{
	"ReadTerminal":    ai.NewTool("ReadTerminal", "Read the latest output from a terminal session owned by this canonical run. Use the session_id returned by TerminalSession.", "{\"type\":\"object\",\"required\":[\"session_id\"],\"properties\":{\"session_id\":{\"type\":\"string\",\"description\":\"TerminalSession session identifier returned by the terminal tool.\"},\"max_bytes\":{\"type\":\"number\",\"minimum\":1,\"maximum\":524288,\"description\":\"Maximum number of recent output bytes to return.\"}},\"additionalProperties\":false}"),
	"TerminalSession": ai.NewTool("TerminalSession", "Start a backend-owned interactive terminal session. The returned session_id can be passed to ReadTerminal.", "{\"type\":\"object\",\"required\":[\"command\"],\"properties\":{\"command\":{\"type\":\"string\",\"description\":\"Shell command to start in the backend-owned terminal session.\"}},\"additionalProperties\":false}"),
	"Read":            ai.NewTool("Read", "Read a text, image, PDF, notebook, Word, Excel/spreadsheet, or archive file from the workspace, a configured root:// project directory, or an enabled Skill. Pass the path exactly as returned by other tools. For text files, use start_line (1-based) and limit for pagination. For PDFs, use page_start and page_limit. For notebooks (.ipynb), use cell_start and cell_limit. Word/Excel/archive files return a best-effort text preview or entry listing. Returns version metadata and may return an `unchanged` stub when content has not changed since the previous read. Use Image instead when the user asks to show, view, render, or display an image in the chat UI. Do not use Markdown image syntax or HTML img tags to display files.", "{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Required file path. Prefer the workspace-relative form such as \\\"src/App.tsx\\\", a configured root://<alias>/... path, or the skill:// form, exactly as returned by other tools; absolute, ~/..., and file:// forms are auto-normalized.\"},\"start_line\":{\"type\":\"number\",\"minimum\":1,\"description\":\"1-based starting line for text files (default: 1)\"},\"limit\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of lines to read for text files (default: 200)\"},\"page_start\":{\"type\":\"number\",\"minimum\":1,\"description\":\"1-based starting page for PDF files (default: 1)\"},\"page_limit\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of PDF pages to read (default: 5)\"},\"cell_start\":{\"type\":\"number\",\"minimum\":1,\"description\":\"1-based starting cell for notebook files (default: 1)\"},\"cell_limit\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of notebook cells to summarize (default: 20)\"}},\"additionalProperties\":false}"),
	"Image":           ai.NewTool("Image", "Display one or more images in the chat UI. This is the only supported way for assistant-side image rendering. Call it whenever the user asks to show, view, render, preview, open, or display images, and whenever another tool saves, downloads, screenshots, generates, or returns an image path/URL that the user should see. Supports workspace paths, configured root:// project paths, enabled Skill paths, external absolute paths, http/https URLs, base64 data URLs, and SVG images (file, data URL, or raw XML). Pass local paths exactly as you see them. For remote images, pass url/urls or source/sources directly instead of downloading the image first, unless the user explicitly asks to save it locally. Do not embed images in final text with Markdown image syntax, HTML img tags, file:// URLs, or local relative image paths.", "{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Single local image path, exactly as returned by other tools. Workspace-relative, root://<alias>/..., skill://, absolute, ~/..., and file:// forms are accepted; external absolute paths are allowed for images.\"},\"paths\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Local image path. Same accepted forms as `path`.\"},\"minItems\":1,\"maxItems\":12,\"description\":\"Multiple local image paths to display in order.\"},\"url\":{\"type\":\"string\",\"description\":\"Single http/https image URL. Use this directly for remote images that only need to be displayed.\"},\"urls\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"http/https image URL\"},\"minItems\":1,\"maxItems\":12,\"description\":\"Multiple remote image URLs to display in order without pre-downloading them.\"},\"base64\":{\"type\":\"string\",\"description\":\"Single image as a data URL or raw base64. For raw base64, provide mimeType when possible.\"},\"base64s\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Image as a data URL or raw base64\"},\"minItems\":1,\"maxItems\":12,\"description\":\"Multiple base64 images to display in order. Prefer data URLs so the MIME type is explicit.\"},\"mimeType\":{\"type\":\"string\",\"description\":\"MIME type for raw base64 input, for example image/png, image/jpeg, or image/svg+xml.\"},\"source\":{\"type\":\"string\",\"description\":\"Single generic image source. Accepted forms: local path, http/https URL, data URL, raw base64, or raw SVG XML. Prefer this for mixed or unknown source types.\"},\"sources\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"description\":\"Generic image source. Same accepted forms as `source`.\"},\"minItems\":1,\"maxItems\":12,\"description\":\"Multiple mixed image sources to display in order. Use this for mixed path + URL + base64 galleries.\"}},\"additionalProperties\":false}"),
	"Write":           ai.NewTool("Write", "Create a new text file or fully overwrite an existing text file in the workspace, a writable root:// project directory, or an enabled writable Skill. `path` must include the intended filename, for example `notes/todo.txt`; Write creates missing parent directories but does not choose filenames from directory paths. Overwriting an existing file replaces its entire content and is checked against the file's current on-disk state automatically. Use Edit for small changes.", "{\"type\":\"object\",\"required\":[\"path\",\"content\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Required file path. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools; absolute and ~/... forms are auto-normalized. A root:// path must name a writable configured root.\"},\"content\":{\"type\":\"string\",\"description\":\"Entire text content to write\"}},\"additionalProperties\":false}"),
	"Edit":            ai.NewTool("Edit", "Perform an exact-string replacement in a file you have already Read. Validates version metadata before writing and rejects stale edits — if the file changed after the last Read, Read it again before retrying. When no exact match exists, Edit automatically retries with lenient matching (CRLF/LF line endings, per-line trailing whitespace, then a uniform indentation shift) and reports the used matchStrategy in the result, so do not pad old_string with guessed whitespace. If `old_string` matches multiple places, either narrow it until unique or set `replace_all=true` explicitly.", "{\"type\":\"object\",\"required\":[\"path\",\"old_string\",\"new_string\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Required file path. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools; absolute and ~/... forms are auto-normalized. A root:// path must name a writable configured root.\"},\"old_string\":{\"type\":\"string\",\"description\":\"Exact text to replace\"},\"new_string\":{\"type\":\"string\",\"description\":\"Replacement text\"},\"expected_replacements\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Expected number of actual replacements. Use together with replace_all for multi-match edits.\"},\"replace_all\":{\"type\":\"boolean\",\"description\":\"Replace every exact match when true; otherwise only a single unambiguous match is allowed\"}},\"additionalProperties\":false}"),
	"Delete":          ai.NewTool("Delete", "The structured, tracked way to intentionally delete a file/directory in the workspace, a writable root:// project directory, or an enabled writable Skill. Directories are removed recursively; use one Delete call per target. Always use this instead of Bash, ManagedProcess, shell scripts, or deletion-oriented CLIs such as rm/rmdir/unlink/find -delete/git rm/git clean/PowerShell Remove-Item/cmd del, erase, or rd. Delete results feed LiveAgent's Edited Files and file-ledger tracking.", "{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Required path to the file or directory. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools. A root:// path must name a writable configured root.\"}},\"additionalProperties\":false}"),
	"List":            ai.NewTool("List", "List files and directories under the workspace, a configured root:// project directory, or an enabled Skill using ignore-aware traversal. Supports depth-limited traversal and paginated results. Prefer this over `Bash ls` / `find` for structured file access.", "{\"type\":\"object\",\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Optional directory to list; a file path returns that single entry. Omit to list the workspace root. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools.\"},\"depth\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Recursion depth (default: 2)\"},\"offset\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Pagination offset (default: 0)\"},\"max_results\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of entries to return (default: 200)\"}},\"additionalProperties\":false}"),
	"Glob":            ai.NewTool("Glob", "Find files by glob pattern under the workspace, a configured root:// project directory, or an enabled Skill using ignore-aware traversal. Results are paginated and sorted by path. Prefer this over `Bash find` for structured file access.", "{\"type\":\"object\",\"required\":[\"pattern\"],\"properties\":{\"pattern\":{\"type\":\"string\",\"description\":\"Glob pattern relative to the search root, for example \\\"**/*.tsx\\\" or \\\"src/**/Chat*.ts\\\". Use `/` as the separator (Windows `\\\\` is auto-normalized).\"},\"path\":{\"type\":\"string\",\"description\":\"Optional base directory to search under. Omit to search from the workspace root. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools.\"},\"offset\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Pagination offset (default: 0)\"},\"max_results\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of results to return (default: 200)\"},\"sort_by\":{\"type\":\"string\",\"const\":\"path\",\"description\":\"Sorting mode. Only path sorting is currently supported.\"}},\"additionalProperties\":false}"),
	"Grep":            ai.NewTool("Grep", "Search file contents under the workspace, a configured root:// project directory, or an enabled Skill using a regular expression with ignore-aware traversal. Supports output_mode=content|files|count, pagination, optional surrounding context, and multiline matching. Prefer this over `Bash grep` / `rg` for structured file access.", "{\"type\":\"object\",\"required\":[\"pattern\"],\"properties\":{\"pattern\":{\"type\":\"string\",\"description\":\"Regular expression to search for in file contents.\"},\"path\":{\"type\":\"string\",\"description\":\"Optional directory or single file to search. Omit to search from the workspace root. Prefer the workspace-relative, root://<alias>/..., or skill:// form returned by other tools.\"},\"file_pattern\":{\"type\":\"string\",\"description\":\"Optional glob filter, for example **/*.ts|**/*.tsx\"},\"ignore_case\":{\"type\":\"boolean\",\"description\":\"Case-insensitive when true (default: true)\"},\"output_mode\":{\"anyOf\":[{\"type\":\"string\",\"const\":\"content\"},{\"type\":\"string\",\"const\":\"files\"},{\"type\":\"string\",\"const\":\"count\"}]},\"head_limit\":{\"type\":\"number\",\"minimum\":1,\"description\":\"Maximum number of rows to return for the selected output mode (default: 200)\"},\"offset\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Pagination offset (default: 0)\"},\"context\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Number of surrounding lines to include around each match (default: 0)\"},\"multiline\":{\"type\":\"boolean\",\"description\":\"Enable multiline regular expression matching when true\"}},\"additionalProperties\":false}"),
	"ManagedProcess":  ai.NewTool("ManagedProcess", "Start, inspect, wait for, read logs for, or stop a long-running local process. Use action=start for foreground commands that should continue while other tools run; output is captured in a managed log. A process that exits on its own while no wait is watching it is reported to you as a message, so do not poll only to learn that it finished.", "{\"type\":\"object\",\"required\":[\"action\"],\"properties\":{\"action\":{\"type\":\"string\",\"description\":\"Process action: start, status, read_log, wait, or stop.\",\"enum\":[\"start\",\"status\",\"read_log\",\"wait\",\"stop\"]},\"command\":{\"type\":\"string\",\"description\":\"Required for action=start. Do not append &.\"},\"cwd\":{\"type\":\"string\",\"description\":\"Optional working directory for action=start.\"},\"label\":{\"type\":\"string\",\"description\":\"Optional display label.\"},\"isolated\":{\"type\":\"boolean\",\"description\":\"Keep the process alive during run cleanup only when explicitly requested.\"},\"process_id\":{\"type\":\"string\",\"description\":\"Process identifier for status, read_log, wait, and stop.\"},\"cursor\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Absolute log-byte cursor already consumed.\"},\"yield_time_ms\":{\"type\":\"number\",\"minimum\":1,\"maximum\":300000,\"description\":\"Maximum wait duration in milliseconds.\"},\"max_bytes\":{\"type\":\"number\",\"minimum\":1,\"maximum\":524288,\"description\":\"Maximum output bytes for read_log and wait.\"}},\"additionalProperties\":false}"),
	"ProcessWait":     ai.NewTool("ProcessWait", "Wait for an existing managed process and read output from its latest cursor. This registration accepts the process_id returned by ManagedProcess as session_id; Bash remains the synchronous tool in this backend.", "{\"type\":\"object\",\"required\":[\"session_id\"],\"properties\":{\"session_id\":{\"type\":\"string\",\"description\":\"ManagedProcess process_id to wait for.\"},\"cursor\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Absolute log-byte cursor already consumed.\"},\"yield_time_ms\":{\"type\":\"number\",\"minimum\":1,\"maximum\":300000,\"description\":\"Maximum wait duration in milliseconds.\"}},\"additionalProperties\":false}"),
	"ProcessStop":     ai.NewTool("ProcessStop", "Stop an existing managed process and its process tree. This registration accepts the process_id returned by ManagedProcess as session_id; Bash remains the synchronous tool in this backend.", "{\"type\":\"object\",\"required\":[\"session_id\"],\"properties\":{\"session_id\":{\"type\":\"string\",\"description\":\"ManagedProcess process_id to stop.\"},\"cursor\":{\"type\":\"number\",\"minimum\":0,\"description\":\"Absolute log-byte cursor already consumed.\"}},\"additionalProperties\":false}"),
}
